#include <Cellerator/compiler/ir/realization/implement_memory_workspace_and_residency_requirements_v1.hh>
#include <set>
#include <tuple>
namespace cellerator::compiler::ir::realization::v1 {namespace{
memory_requirement_status_v1 fail(memory_requirement_status_v1 s,std::string*e,const char*m)noexcept{if(e)*e=m;return s;}bool pow2(std::uint32_t v){return v&&(v&(v-1))==0;}}
memory_requirement_status_v1 validate_memory_requirements_v1(const std::vector<memory_requirement_v1>&r,std::string*e)noexcept{std::set<std::tuple<std::uint64_t,std::uint64_t>>ids;for(const auto&x:r){if(!valid(x.identity)||!ids.emplace(x.identity.high,x.identity.low).second)return fail(memory_requirement_status_v1::invalid_identity,e,"unique requirement identity required");if(!x.bytes||x.capacity_bytes<x.bytes)return fail(memory_requirement_status_v1::invalid_capacity,e,"capacity must cover bytes");if(!pow2(x.alignment))return fail(memory_requirement_status_v1::invalid_alignment,e,"power-of-two alignment required");if(x.allocation==allocation_class_v1::graph_stable&&x.lifetime==plane_lifetime_v1::invocation)return fail(memory_requirement_status_v1::invalid_lifetime,e,"graph-stable allocation cannot be invocation-lived");}if(e)e->clear();return memory_requirement_status_v1::valid;}
memory_requirement_status_v1 compare_memory_requirements_v1(const std::vector<memory_requirement_v1>&r,const session_memory_accounting_v1&a,std::string*e)noexcept{auto s=validate_memory_requirements_v1(r,e);if(s!=memory_requirement_status_v1::valid)return s;std::uint64_t host=0,device=0,transient=0;for(const auto&x:r){if(x.address_space==address_space_class_v1::host)host+=x.capacity_bytes;else device+=x.capacity_bytes;if(x.allocation==allocation_class_v1::transient)transient+=x.capacity_bytes;}if(host>a.host_capacity)return fail(memory_requirement_status_v1::insufficient_host,e,"host capacity insufficient");if(device+a.persistent_used+a.graph_stable_used>a.device_capacity)return fail(memory_requirement_status_v1::insufficient_device,e,"device capacity insufficient");if(transient>a.transient_available)return fail(memory_requirement_status_v1::insufficient_transient,e,"transient workspace insufficient");if(e)e->clear();return memory_requirement_status_v1::valid;}
} // namespace cellerator::compiler::ir::realization::v1
